package software.amazon.smithy.build.processor;

import java.io.IOException;
import java.io.OutputStream;
import java.io.UncheckedIOException;
import java.io.Writer;
import java.lang.annotation.Annotation;
import java.nio.charset.StandardCharsets;
import java.nio.file.Path;
import java.util.Optional;
import java.util.Set;
import javax.annotation.processing.AbstractProcessor;
import javax.annotation.processing.Filer;
import javax.annotation.processing.Messager;
import javax.annotation.processing.ProcessingEnvironment;
import javax.annotation.processing.RoundEnvironment;
import javax.lang.model.SourceVersion;
import javax.lang.model.element.Element;
import javax.lang.model.element.PackageElement;
import javax.lang.model.element.TypeElement;
import javax.tools.Diagnostic;
import javax.tools.StandardLocation;
import software.amazon.smithy.build.FileManifest;
import software.amazon.smithy.build.MockManifest;
import software.amazon.smithy.build.PluginContext;
import software.amazon.smithy.build.SmithyBuildPlugin;
import software.amazon.smithy.model.Model;
import software.amazon.smithy.model.node.ObjectNode;
import software.amazon.smithy.utils.SetUtils;

/**
 * Abstract annotation processor that can be used to easily generate Smithy
 * code in the context of a package.
 *
 * <p>This annotation processor is designed to be extended by other libraries
 * that want to generate code (e.g., generating code for custom traits) when a
 * package is annotated with a given annotation. Extending classes define the
 * name of the {@link SmithyBuildPlugin} to execute, the annotation type that
 * triggers the processor, and the mapping from the annotation to a plugin
 * configuration using {@link #createPluginNode(Annotation, String)}.</p>
 *
 * <p>When an annotated package is found, the processor loads all Smithy models
 * that can be discovered on the classpath into a {@link Model}, creates a
 * {@link PluginContext} with the model and the plugin configuration node, and
 * executes the plugin.</p>
 *
 * <p>Java source files generated by the plugin are written to the generated
 * source output location using {@link Filer#createSourceFile}. Resource files
 * generated under {@code META-INF/} are written to the generated class output
 * location using {@link Filer#createResource}. Any other generated artifact is
 * ignored, and a NOTE diagnostic is emitted for each ignored artifact.</p>
 *
 * @param <T> Type of annotation that triggers the processor.
 */
public abstract class SmithyAnnotationProcessor<T extends Annotation> extends AbstractProcessor {
    private static final String META_INF_PATH = "META-INF/";

    private Filer filer;
    private Messager messager;

    @Override
    public synchronized void init(ProcessingEnvironment processingEnv) {
        super.init(processingEnv);
        filer = processingEnv.getFiler();
        messager = processingEnv.getMessager();
    }

    @Override
    public final Set<String> getSupportedAnnotationTypes() {
        return SetUtils.of(getAnnotationClass().getCanonicalName());
    }

    @Override
    public final SourceVersion getSupportedSourceVersion() {
        // Allow the processor to run on the latest supported source version.
        return SourceVersion.latestSupported();
    }

    @Override
    public final boolean process(Set<? extends TypeElement> annotations, RoundEnvironment roundEnv) {
        if (!roundEnv.processingOver()) {
            for (Element element : roundEnv.getElementsAnnotatedWith(getAnnotationClass())) {
                processElement(element);
            }
        }
        return false;
    }

    /**
     * Gets the name of the {@link SmithyBuildPlugin} to execute.
     *
     * @return Returns the name of the plugin to execute.
     */
    protected abstract String getPluginName();

    /**
     * Gets the class of the annotation that triggers the processor.
     *
     * @return Returns the annotation class.
     */
    protected abstract Class<T> getAnnotationClass();

    /**
     * Creates the configuration node to pass to the executed
     * {@link SmithyBuildPlugin}.
     *
     * @param annotation Annotation that triggered the processor.
     * @param packageName Package that contains the annotation.
     * @return Returns the plugin configuration node.
     */
    protected abstract ObjectNode createPluginNode(T annotation, String packageName);

    private void processElement(Element element) {
        PackageElement packageElement = getPackage(element);
        String packageName = packageElement == null ? "" : packageElement.getQualifiedName().toString();

        Optional<SmithyBuildPlugin> plugin = SmithyBuildPlugin.createServiceFactory().apply(getPluginName());
        if (!plugin.isPresent()) {
            messager.printMessage(Diagnostic.Kind.ERROR,
                    "Could not find a Smithy build plugin named `" + getPluginName() + "`");
            return;
        }

        Model model = Model.assembler().discoverModels().assemble().unwrap();
        FileManifest manifest = new MockManifest();

        PluginContext context = PluginContext.builder()
                .model(model)
                .settings(createPluginNode(element.getAnnotation(getAnnotationClass()), packageName))
                .fileManifest(manifest)
                .build();
        plugin.get().execute(context);

        for (Path path : manifest.getFiles()) {
            String fileName = path.toString();
            if (fileName.startsWith("/")) {
                fileName = fileName.substring(1);
            }

            if (fileName.endsWith(".java")) {
                writeSourceFile(fileName, manifest.expectFileBytes(path));
            } else if (fileName.startsWith(META_INF_PATH)) {
                writeResourceFile(fileName, manifest.expectFileBytes(path));
            } else {
                messager.printMessage(Diagnostic.Kind.NOTE,
                        "Ignoring Smithy build plugin artifact: `" + fileName + "`");
            }
        }
    }

    private void writeSourceFile(String fileName, byte[] contents) {
        String className = fileName.substring(0, fileName.length() - ".java".length())
                .replace('/', '.')
                .replace('\\', '.');
        try (Writer writer = filer.createSourceFile(className).openWriter()) {
            writer.write(new String(contents, StandardCharsets.UTF_8));
        } catch (IOException e) {
            throw new UncheckedIOException(e);
        }
    }

    private void writeResourceFile(String fileName, byte[] contents) {
        try (OutputStream outputStream = filer
                .createResource(StandardLocation.CLASS_OUTPUT, "", fileName)
                .openOutputStream()) {
            outputStream.write(contents);
        } catch (IOException e) {
            throw new UncheckedIOException(e);
        }
    }

    private static PackageElement getPackage(Element element) {
        while (!(element instanceof PackageElement)) {
            element = element.getEnclosingElement();
        }
        return (PackageElement) element;
    }
}

