package software.amazon.smithy.build.processor.test;

import software.amazon.smithy.build.FileManifest;
import software.amazon.smithy.build.PluginContext;
import software.amazon.smithy.build.SmithyBuildPlugin;
import software.amazon.smithy.model.loader.Prelude;
import software.amazon.smithy.model.shapes.Shape;

/**
 * A {@link SmithyBuildPlugin} used to test {@code SmithyAnnotationProcessor}.
 *
 * <p>The plugin generates a Java source file for each non-prelude shape in the
 * model, a Smithy model resource under {@code META-INF/smithy}, and an artifact
 * that is intentionally ignored by the annotation processor.</p>
 */
public final class TraitsPlugin implements SmithyBuildPlugin {
    /** Name of the plugin. */
    public static final String PLUGIN_NAME = "traits";

    @Override
    public String getName() {
        return PLUGIN_NAME;
    }

    @Override
    public void execute(PluginContext context) {
        String packageName = context.getSettings().expectStringMember("packageName").getValue();
        String directory = packageName.replace('.', '/');
        FileManifest manifest = context.getFileManifest();

        for (Shape shape : context.getModel().shapes()) {
            if (!Prelude.isPreludeShape(shape)) {
                String shapeName = shape.getId().getName();
                manifest.writeFile(directory + "/" + shapeName + ".java",
                        "package " + packageName + ";\n\npublic final class " + shapeName + " {}\n");
            }
        }

        manifest.writeFile("META-INF/smithy/generated-traits.smithy",
                "$version: \"2.0\"\n\nnamespace " + packageName + "\n");
        manifest.writeFile("META-INF/smithy/manifest", "generated-traits.smithy\n");

        // This artifact is not generated with a .java extension or a META-INF/
        // prefix, so the annotation processor emits a NOTE and ignores it.
        manifest.writeFile("ignored.txt", "This artifact is intentionally ignored.\n");
    }
}

