package software.amazon.smithy.model.validation;

import static org.hamcrest.MatcherAssert.assertThat;
import static org.hamcrest.Matchers.equalTo;

import org.junit.jupiter.api.Test;
import software.amazon.smithy.model.node.Node;

public class ValidationUtilsTest {
    @Test
    public void ticksSingleLineValues() {
        assertThat(ValidationUtils.tickedPrettyPrintedNode(Node.from(true)), equalTo("`true`"));
        assertThat(ValidationUtils.tickedPrettyPrintedNode(Node.from(false)), equalTo("`false`"));
        assertThat(ValidationUtils.tickedPrettyPrintedNode(Node.from(10)), equalTo("`10`"));
        assertThat(ValidationUtils.tickedPrettyPrintedNode(Node.from(10.0)), equalTo("`10.0`"));
        assertThat(ValidationUtils.tickedPrettyPrintedNode(Node.nullNode()), equalTo("`null`"));
        assertThat(ValidationUtils.tickedPrettyPrintedNode(Node.objectNode()), equalTo("`{}`"));
        assertThat(ValidationUtils.tickedPrettyPrintedNode(Node.arrayNode()), equalTo("`[]`"));
    }

    @Test
    public void ticksSingleLineStringsWithoutQuotes() {
        assertThat(ValidationUtils.tickedPrettyPrintedNode(Node.from("foo")), equalTo("`foo`"));
        assertThat(ValidationUtils.tickedPrettyPrintedNode(Node.from("")), equalTo("``"));
    }

    @Test
    public void wrapsMultiLineValuesInFencedCodeBlocks() {
        Node array = Node.arrayNode()
                .withValue(Node.from(1))
                .withValue(Node.from(2));
        assertThat(ValidationUtils.tickedPrettyPrintedNode(array),
                   equalTo(String.format("%n```%n[%n    1,%n    2%n]%n```%n")));

        Node object = Node.objectNode().withMember("foo", Node.from("bar"));
        assertThat(ValidationUtils.tickedPrettyPrintedNode(object),
                   equalTo(String.format("%n```%n{%n    \"foo\": \"bar\"%n}%n```%n")));
    }
}

