import software.amazon.smithy.syntax.TokenTree;
import software.amazon.smithy.syntax.Formatter;
import software.amazon.smithy.model.loader.IdlTokenizer;

public class Main {
    public static void main(String[] args) throws Exception {
        String model = args.length > 0 ? String.join("\n", java.util.Arrays.copyOfRange(args, 0, args.length)) : "";
        // read model from stdin if no args
        if (args.length == 0) {
            StringBuilder sb = new StringBuilder();
            java.io.BufferedReader r = new java.io.BufferedReader(new java.io.InputStreamReader(System.in));
            String line;
            while ((line = r.readLine()) != null) {
                sb.append(line).append('\n');
            }
            model = sb.toString();
        }
        IdlTokenizer tokenizer = IdlTokenizer.create("test.smithy", model);
        TokenTree tree = TokenTree.of(tokenizer);
        System.out.println("=== TREE ===");
        System.out.println(tree);
        System.out.println("=== ROOT LOCATION ===");
        System.out.println("start(line,col)=" + tree.getStartLine() + "," + tree.getStartColumn()
                + " end=" + tree.getEndLine() + "," + tree.getEndColumn()
                + " sourceLoc=" + tree.getSourceLocation());
        System.out.println("=== FORMATTED ===");
        try {
            System.out.println(">>>" + Formatter.format(tree, 120) + "<<<");
        } catch (Exception e) {
            System.out.println("Formatter error: " + e.getMessage());
        }
    }
}

